"""R-013: one non-overlapping leg linkage table (Actuators view, reconciles modules/legs/LINKAGE_TABLE.md). -> results/LINKAGE_TABLE.md/.json and mass rollup."""
import json, os, math
H=os.path.dirname(os.path.abspath(__file__)); cm=json.load(open(f'{H}/results/cad_mass.json')); fe=json.load(open(f'{H}/results/hp_lever_fea_r4.json')); fe0=json.load(open(f'{H}/results/hp_lever_fea.json')); nd=json.load(open(f'{H}/results/hp_pivot_needle.json'))
R=[ # part, owner, kg each, n per leg, source, confirm-by-Legs flag
 ('hip_pitch lever, config B, needle-cheek hub, SF 1.5 + proof test (2 halves, loft arms, ears; dy 69), 7075 + 2 steel pins ø12x25','Actuators',fe['mass_kg'],1,'CAD+FEA hp_lever_fea.py HUB=needle (R4), was 0.371 at SF 2.13',''),
 ('hip_pitch pivot: 2x IKO TLA 3520 Z needle + hardened shaft ø35/30x67 + thrust washers + circlips','Actuators',nd['mass_line'],1,'datasheet 2x0.0435 + shaft CAD-calc + washers [EST]; replaces CRBH 5013 A line 0.314','Legs: tongue bore ø35 press fit (not ø80)'),
 ('knee lever r47.5','Actuators',cm['knee_lever_r47p5']['mass'],1,'CAD','v3 knee-lever credit dropped (Legs L14 accepted)'),
 ('nut-rotor hub','Actuators',cm['nut_rotor_hub_x1']['mass'],6,'CAD',''),
 ('trunnion pin pair ø16/ø9 steel (knee + ankle bodies; hip bodies now on clamp eyes, R5b)','Actuators',cm['trunnion_pins_pair']['mass'],4,'CAD; 6 -> 4 pairs/leg (Legs L18 clamp form, P-014)',''),
 ('hip_pitch body axial eye: SKF GE 12 E in 7075 eye on body end + ø12x28 42CrMo4 pin in clamp arm','Actuators',0.035+math.pi/4*12**2*28*7.85e-6,2,'GE 12 E datasheet 0.016 + eye 0.019 CAD-calc + pin calc; clamp_review.py','Legs: clamp arm bore ø12 H7'),
 ('ankle_pitch 73 mm lever (R5b): 2 RV12 screws +4 mm and 2 body tubes +4 mm for +4.3 % stroke','Actuators',2*(math.pi/4*12**2*4*7.85e-6)+2*(math.pi*40*2*4*2.81e-6),1,'calc; size.py ARM_FIX 0.073','Legs: instep lug pin radius 70 -> 73 mm'),
 ('rod-end: SKF GE 12 E spherical plain bearing (0.016 kg, C0 54 kN) in a 7075 eye ø30x12 with M12 boss (0.019 kg CAD-calc)','Actuators',0.035,6,'datasheets/skf_ge12e.pdf; catalog SIKAC 12 M (0.118 kg, C0 14 kN) rejected: 3.4x heavier',''),
 ('ankle rod-end lugs on foot instep (2)','Legs',0.0,1,'0.042/leg counted in Legs M2 line (L19); removed here (−0.084 both legs, R5b)',''),
 ('thigh split-collar clamp for hip_pitch bodies','Legs',0.0,1,'0.237/leg counted in Legs M2 line (L18); Actuators review clamp_review.json: bond + light clamp required',''),
]
rows=[]; tot=0
for p,o,m,n,src,fl in R:
    kl=None if m is None else m*n; tot+=kl or 0; rows.append(dict(part=p,owner=o,kg_each=m,n_per_leg=n,kg_per_leg=kl,source=src,legs_confirm=fl))
base_leg=cm['per_leg']['linkage']   # 0.3043 per leg in the 65.79 rollup (contract 0.609 both legs)
out=dict(rows=rows,per_leg=tot,both_legs=2*tot,contract_both=0.609,delta_vs_rollup=2*tot-2*base_leg)
M0=65.79;  # R3 CAD-supported base; R-016 adds thigh clamp 0.20 (Legs line) on top
act=dict(hip_lever=2*(fe['mass_kg']-cm['hip_pitch_lever_r50']['mass']),hip_bearing=2*nd['mass_line'])
corr=out['delta_vs_rollup']-act['hip_lever']-act['hip_bearing']
out['rollup']=dict(base_CAD_supported=M0,actuators_r3b_hip=act,other_linkage_corrections=corr,thigh_clamp_R016=0.20,new_total=M0+out['delta_vs_rollup']+0.20,
   if_legs_structure_and_torso_land=M0+out['delta_vs_rollup']+0.20-0.56-0.80,limit=65.0)
hz=json.load(open(f'{H}/results/harness.json'))
# R6: rollup on the Arbiter's R-020 basis (credible 66.89 incl. linkage 2.326 both legs and harness credited 1.324)
R20=dict(robot=66.89,harness=1.324,link_both=2.326)
link_delta=2*tot-R20['link_both']
out['harness']=dict(model_kg=hz['total_kg'],R020_credited=R20['harness'],delta=hz['total_kg']-R20['harness'],src='results/harness.json (harness.py)')
out['rollup_r6']=dict(base_R020_credible=R20['robot'],linkage_delta=link_delta,harness_delta=out['harness']['delta'],robot=R20['robot']+link_delta+out['harness']['delta'],limit=66.5,
   A1prime_pending=-0.596-0.028+0.028,robot_if_A1prime=R20['robot']+link_delta+out['harness']['delta']-0.596)
json.dump(out['rollup_r6']|dict(harness=out['harness']),open(f'{H}/results/mass_rollup_r6.json','w'),indent=1)
json.dump(out,open(f'{H}/results/LINKAGE_TABLE.json','w'),indent=1)
L=['# Leg linkage table (Actuators, R-013 / R3b) — one table, no double counting','',
 'Generated by `linkage_table.py` from `cad_mass.json`, `hp_lever_fea.json`, `hp_bearing.json`. Supersedes the Actuators side of `modules/legs/LINKAGE_TABLE.md` (Legs keeps its file; numbers below are the ones to roll up).','',
 '| part | owner | kg each | n/leg | kg/leg | source | Legs must confirm |','|---|---|---|---|---|---|---|']
for r in rows: L.append(f"| {r['part']} | {r['owner']} | {'' if r['kg_each'] is None else round(r['kg_each'],4)} | {r['n_per_leg']} | {'OPEN' if r['kg_per_leg'] is None else round(r['kg_per_leg'],4)} | {r['source']} | {r['legs_confirm']} |")
L+=['',f"**Total {tot:.3f} kg/leg = {2*tot:.3f} kg both legs** (contract 0.609; rollup used {2*base_leg:.3f}). Open: thigh trunnion clamp (Legs).",'',
 'No double counting: Legs structure 4.85 kg excludes all lever solids, bearings, pins, hubs, rod-ends (L8/L14); actuator housings (cad_mass.json housing group) exclude everything above. Ankle lever: the ankle rod-ends act on the Legs instep lugs (no separate Actuators ankle lever solid). Nut-rotor hubs: 2 per twin-screw unit x 3 units = 6/leg = 12 both legs (R-013 count, 0.192 kg).','',
 f"Rollup: {M0} + {out['delta_vs_rollup']:.3f} + thigh clamp 0.20 (R-016 [EST]) = **{M0+out['delta_vs_rollup']+0.2:.2f} kg** CAD-supported (of which Actuators R3b hip_pitch lever +{act['hip_lever']:.3f}, pivot bearing +{act['hip_bearing']:.3f}; other linkage corrections +{corr:.3f}). If Legs structure (−0.56) and Torso (−0.80) land: {M0+out['delta_vs_rollup']+0.2-1.36:.2f} kg vs 66.5 kg hard (R-017). Harness M3 not included here (see results/harness.md)."]
rb=out['rollup_r6']; L+=['',f"**Harness line (generated from `results/harness.json`):** {hz['total_kg']:.3f} kg vs R-020 credited 1.324 → {out['harness']['delta']:+.3f} kg.",
 f"**R6 rollup (R-020 basis):** credible 66.89 {rb['linkage_delta']:+.3f} linkage {rb['harness_delta']:+.3f} harness = **{rb['robot']:.3f} kg** vs 66.5 hard. With A1' (Grok Build FEA, −0.596) → {rb['robot_if_A1prime']:.3f} kg."]
open(f'{H}/results/LINKAGE_TABLE.md','w').write('\n'.join(L)+'\n'); print('\n'.join(L[-3:]))
